package control_flow.assigment_problems;
public class GuessTheNumberGame { public static void guessTheNumber(int secretNumber,int maxTries,int[] guesses){int tries=0;boolean correct=false;while(tries<maxTries&&tries<guesses.length&&!correct){int guess=guesses[tries++];if(guess==secretNumber){System.out.println("Correct! You guessed it");correct=true;break;}else if(guess>secretNumber)System.out.println("Too high");else System.out.println("Too low");}if(!correct)System.out.println("Out of tries — the number was "+secretNumber);} public static void main(String[] a){guessTheNumber(42,4,new int[]{20,60,42});} }